import{g as o,ad as t,r as a,A as c}from"./chunks/framework.Bv4C6ofj.js";const m=JSON.parse('{"title":"Legacy components","description":"","frontmatter":{},"headers":[],"relativePath":"docs/components/legacy.md","filePath":"docs/components/legacy.md","lastUpdated":1786054874000}'),r={name:"docs/components/legacy.md"};function n(d,e,s,i,l,p){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="legacy-components" tabindex="-1">Legacy components <a class="header-anchor" href="#legacy-components" aria-label="Permalink to “Legacy components”">​</a></h1><p>These components are deprecated and emit a <code>console.warn</code> in development. They remain in the library for now to keep existing apps building, but new code should use the replacements listed below. Each will be removed in a future major release.</p><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to “Input”">​</a></h2><p>Replaced by <a href="./textinput"><code>TextInput</code></a> for text-like inputs (<code>text</code>, <code>number</code>, <code>email</code>, <code>password</code>, <code>date</code>), <a href="./textarea"><code>Textarea</code></a>, <a href="./select"><code>Select</code></a>, and <a href="./checkbox"><code>Checkbox</code></a> for the other type modes the original <code>Input</code> accepted.</p><p><code>TextInput</code> and friends share a labeling contract (<code>label</code>, <code>description</code>, <code>error</code>, <code>required</code>) and a sized/variant API that the legacy <code>Input</code> component does not.</p><h2 id="removed-in-v1" tabindex="-1">Removed in v1 <a class="header-anchor" href="#removed-in-v1" aria-label="Permalink to “Removed in v1”">​</a></h2><p>These are no longer in the library. The <a href="./../migration#autocomplete-removed">migration guide</a> has a before/after for each.</p><ul><li><strong><code>Autocomplete</code></strong> — use <a href="./combobox"><code>Combobox</code></a> for single-select and <a href="./multiselect"><code>MultiSelect</code></a> for multi-select. Both use the shared input primitives, render the same label/description/error contract as the rest of the v1 input family, and have a smaller, more predictable API surface.</li><li><strong><code>FormControl type=&quot;autocomplete&quot;</code></strong> — use <code>type=&quot;combobox&quot;</code>, or a standalone <a href="./combobox"><code>Combobox</code></a>, which exposes the full set of slots and props without the wrapper layer. Removing this one is <strong>silent</strong>: the type falls through to a plain text input rather than failing.</li></ul>',8)])])}const u=o(r,[["render",n]]);export{m as __pageData,u as default};
